#include <bits/stdc++.h>
using namespace std;
struct Seg{int n;vector<int>s;vector<signed char>t;Seg(int n):n(n),s(4*n+4),t(4*n+4,-1){};void ap(int o,int l,int r,int v){s[o]=v?r-l+1:0;t[o]=v;}void ps(int o,int l,int r){if(t[o]==-1||l==r)return;int m=(l+r)/2;ap(o*2,l,m,t[o]);ap(o*2+1,m+1,r,t[o]);t[o]=-1;}void as(int o,int l,int r,int ql,int qr,int v){if(ql>r||qr<l||ql>qr)return;if(ql<=l&&r<=qr){ap(o,l,r,v);return;}ps(o,l,r);int m=(l+r)/2;as(o*2,l,m,ql,qr,v);as(o*2+1,m+1,r,ql,qr,v);s[o]=s[o*2]+s[o*2+1];}void as(int l,int r,int v){if(l<=r)as(1,1,n,l,r,v);}int total(){return s[1];}};
long long fast(const vector<int>&x){int n=x.size();vector<int>a(n+1),pre(n+1),last(n+1);for(int i=1;i<=n;i++){a[i]=x[i-1];pre[i]=last[a[i]];last[a[i]]=i;}vector<int>lg(n+1);for(int i=2;i<=n;i++)lg[i]=lg[i/2]+1;int K=lg[n]+1;vector<vector<int>>st(K,vector<int>(n+1));for(int i=1;i<=n;i++)st[0][i]=pre[i];for(int k=1;(1<<k)<=n;k++)for(int i=1;i+(1<<k)-1<=n;i++)st[k][i]=min(st[k-1][i],st[k-1][i+(1<<(k-1))]);auto rmq=[&](int l,int r){int k=lg[r-l+1];return min(st[k][l],st[k][r-(1<<k)+1]);};vector<int>L(n+1),R(n+1);int tail=0;Seg seg(n);long long ans=0;for(int r=1;r<=n;r++){int p=pre[r],q=0,t=0;if(p){q=L[p];t=R[p];}seg.as(p+1,r,0);if(p){int nl=t?t:r;int mn=rmq(nl,r),cut=min(p,mn);if(q+1<=cut)seg.as(q+1,cut,1);if(q)R[q]=t;if(t)L[t]=q;else tail=q;}L[r]=tail;R[r]=0;if(tail)R[tail]=r;tail=r;ans+=seg.total();}return ans;}
long long brute(const vector<int>&a){int n=a.size();long long ans=0;for(int l=0;l<n;l++){for(int r=l+1;r<n;r++){unordered_map<int,pair<int,int>>mp;for(int i=l;i<=r;i++){auto it=mp.find(a[i]);if(it==mp.end())mp[a[i]]={i,i};else it->second.second=i;}int F=l,L=r;for(auto &kv:mp){F=max(F,kv.second.first);L=min(L,kv.second.second);}ans+=(F<L);}}return ans;}
int main(){uint64_t cnt=0;for(int n=1;n<=10;n++){long long tot=1;for(int i=0;i<n;i++)tot*=3;for(long long code=0;code<tot;code++){long long z=code;vector<int>a(n);for(int i=0;i<n;i++){a[i]=1+z%3;z/=3;}auto f=fast(a),b=brute(a);++cnt;if(f!=b){cerr<<"FAIL exhaustive n="<<n<<" code="<<code<<" f="<<f<<" b="<<b<<"\n";for(int x:a)cerr<<x<<' ';cerr<<'\n';return 1;}}}
mt19937 rng(27182818);for(int tc=0;tc<1000000;tc++){int n=1+rng()%30;int k=1+rng()%min(n,7);vector<int>a(n);for(int&i:a)i=1+rng()%k;auto f=fast(a),b=brute(a);++cnt;if(f!=b){cerr<<"FAIL random tc="<<tc<<" n="<<n<<" f="<<f<<" b="<<b<<"\n";for(int x:a)cerr<<x<<' ';cerr<<'\n';return 1;}}
cout<<"PASS "<<cnt<<" arrays\n";
}